def season(d):
    return {12: 'winter', 1: 'winter', 2: 'winter', 3: 'spring', 4: 'spring', 5: 'spring', 6: 'summer', 7: 'summer', 8: 'summer', 9: 'autumn', 10: 'autumn', 11: 'autumn'}[d.month]

if __name__ == '__main__':
    import sys
    part2 = '--part2' in sys.argv
    if part2: L, SRC = L2, os.path.join(HERE, 'good-src2')
    info = json.load(open(os.path.join(HERE, 'good-info2.json' if part2 else 'good-info.json')))
    for sub in ('full', 'web', 'thumb'): os.makedirs(os.path.join(OUT, sub), exist_ok=True)
    rows = []
    for (f, key, title, alt, scene, people, usage, note, pick, best, tags, x) in L:
        im = ImageOps.exif_transpose(Image.open(os.path.join(SRC, f))).convert('RGB')
        w0, h0 = im.size
        sizes = {}
        for sub, mx, q in (('full', 2400, 84), ('web', 1600, 80), ('thumb', 640, 76)):
            r = im.copy(); r.thumbnail((mx, mx), Image.LANCZOS)
            p = os.path.join(OUT, sub, key + '.jpg'); r.save(p, 'JPEG', quality=q, optimize=True, progressive=True)
            sizes[sub] = (r.size, os.path.getsize(p))
        (fw, fh), _ = sizes['full']
        avg = ImageStat.Stat(im.resize((32, 32))).mean
        dt = info[f]['dt']; taken = None
        if x.get('taken'): taken = datetime.date.fromisoformat(x['taken'])
        elif dt and not x.get('film'):
            try: taken = datetime.datetime.strptime(dt[:10], '%Y:%m:%d').date()
            except ValueError: taken = None
        sunday = taken and taken.weekday() == 6
        rows.append({
            'key': key, 'title': title, 'alt_text': alt, 'caption': title, 'description': alt,
            'taken_on': taken.isoformat() if taken else None,
            'date_note': x.get('date_note') or (FILM if x.get('film') else ('From the camera (a Sunday).' if sunday else ('From the camera.' if taken else None))),
            'season': season(taken) if taken else None, 'place': x.get('place', 'Montreal'),
            'event': x.get('event') or ('Sunday serving' if sunday else ('Serving' if taken else None)), 'scene': scene, 'tags': tags,
            'usage': usage, 'usage_note': note, 'people': people, 'partner': x.get('partner') or [], 'branding': 'legacy vests and tent (before the 2026 brand)',
            'series': x.get('series'), 'is_pick': pick, 'orientation': 'portrait' if fh > fw * 1.05 else ('landscape' if fw > fh * 1.05 else 'square'),
            'width': fw, 'height': fh, 'focal_x': (x.get('focal') or (0.5, 0.5))[0], 'focal_y': (x.get('focal') or (0.5, 0.5))[1],
            'color': '#%02X%02X%02X' % tuple(int(c) for c in avg[:3]), 'best_for': best, 'credit': None,
            'path_full': 'photos/full/%s.jpg' % key, 'path_web': 'photos/web/%s.jpg' % key, 'path_thumb': 'photos/thumb/%s.jpg' % key,
            'bytes_full': sizes['full'][1], 'bytes_web': sizes['web'][1], 'bytes_thumb': sizes['thumb'][1], 'version': 1, 'status': 'ready',
            'source': ACK % ('%d x %d' % (w0, h0), info[f]['model'] or 'camera unknown') + (' ' + f if True else ''), 'labelled_by': 'Claude (Cowork), 28/09/26',
            'created_by': 'wave162 (assistant)', 'updated_by': 'wave162 (assistant)'})
    json.dump(rows, open(os.path.join(OUT, 'rows2.json' if part2 else 'rows.json'), 'w'), indent=1, ensure_ascii=False)
    tot = sum(r['bytes_full'] + r['bytes_web'] + r['bytes_thumb'] for r in rows)
    print(len(rows), 'photos;', sum(r['usage'] == 'ready' for r in rows), 'ready,', sum(r['usage'] == 'crop' for r in rows), 'crop,', sum(r['usage'] == 'consent' for r in rows), 'consent;', sum(r['is_pick'] for r in rows), 'picks;', tot // 1048576, 'MB of files')
